+    \item \textbf{Probabilité de l'événement contraire :}
+    $$P(\overline{F \cup B}) = 1 - P(F \cup B) = 1 - 0,55 = 0,45$$
+    \item \textbf{Probabilité de pratiquer uniquement le football :}
+    $$\frac{80 - 20}{200} = \frac{60}{200} = 0,3$$
+\end{enumerate}
+
